arguments.command:
cd /root/.openclaw/workspace && rm -rf docs_rot13 && mkdir -p docs_rot13 && python - <<'PY'
import os, codecs, shutil
src='/usr/lib/node_modules/openclaw/docs'
dst='/root/.openclaw/workspace/docs_rot13'
text_ext={'.md','.markdown','.txt','.json','.yaml','.yml','.toml','.ini','.js','.ts','.mjs','.cjs','.css','.html','.htm','.xml','.csv','.tsv','.sh','.py','.rb','.go','.rs','.java','.kt','.swift','.c','.h','.cpp','.hpp','.cs','.php','.pl','.sql'}
for root, dirs, files in os.walk(src):
    rel=os.path.relpath(root, src)
    out_root=os.path.join(dst, rel) if rel!='.' else dst
    os.makedirs(out_root, exist_ok=True)
    for fn in files:
        sp=os.path.join(root, fn)
        dp=os.path.join(out_root, fn)
        ext=os.path.splitext(fn)[1].lower()
        try:
            if ext in text_ext:
                with open(sp,'rb') as f:
                    data=f.read()
                # best-effort decode
                try:
                    s=data.decode('utf-8')
                    enc='utf-8'
                except UnicodeDecodeError:
                    try:
                        s=data.decode('latin-1')
                        enc='latin-1'
                    except Exception:
                        shutil.copy2(sp, dp)
                        continue
                rot=codecs.encode(s,'rot_13')
                with open(dp,'wb') as f:
                    f.write(rot.encode(enc, errors='replace'))
            else:
                shutil.copy2(sp, dp)
        except Exception:
            # if anything weird, just copy
            try:
                shutil.copy2(sp, dp)
            except Exception:
                pass
PY
zip -qr docs_rot13.zip docs_rot13
ls -lh docs_rot13.zip
